<?php require_once __DIR__.'/functions.php'; if(!empty($_SESSION['is_admin'])) redirect('admin.php'); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){if(hash_equals(ADMIN_USER,$_POST['username']??'')&&hash_equals(ADMIN_PASS,$_POST['password']??'')){$_SESSION['is_admin']=true;redirect('admin.php');}$error='بيانات الدخول غير صحيحة.';} ?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>دخول الإدارة | نُقطة</title><link rel="stylesheet" href="assets/style.css"></head><body><main class="container"><div class="form-wrap" style="max-width:480px;margin-top:100px"><span class="eyebrow">منطقة خاصة</span><h1>دخول الإدارة</h1><?php if($error):?><div class="summary"><?=e($error)?></div><?php endif;?><form method="post"><div class="field"><label>اسم المستخدم</label><input name="username" required></div><div class="field"><label>كلمة المرور</label><input type="password" name="password" required></div><button class="btn">دخول</button></form></div></main></body></html>
